var o=[{base:"mastodon_mock_token",storage:"local",suffix:"none",sensitivity:"secret",note:"Active Mastodon bearer token."},{base:"mastodon_mock_session_tokens",storage:"local",suffix:"none",sensitivity:"secret",note:"Bearer token per saved session, keyed by session id. Split out of mastodon_mock_sessions so the account list can be exported."},{base:"mockingbird_bsky_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"Bluesky access + refresh JWTs. Split out of mockingbird_bsky_profile."},{base:"mockingbird_github_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"GitHub personal access token. Split out of mockingbird_github_user."},{base:"mockingbird_raindrop_token",storage:"local",suffix:"none",sensitivity:"secret",note:"Raindrop.io test token. Unscoped: one bookmark drawer per browser, shared by every account. An account-suffixed copy from before that change is adopted on first read and may linger."},{base:"mockingbird_mataroa_connection",storage:"local",suffix:"account",sensitivity:"secret",note:"Mataroa API key plus the linked public blog URL and profile-feed opt-in. Account-scoped because the blog is part of one public persona."},{base:"mockingbird_paste_edit_keys",storage:"local",suffix:"none",sensitivity:"secret",note:"Per-paste edit codes. A bearer capability: whoever holds one can rewrite or delete that paste. Split out of mockingbird_pastes."},{base:"mockingbird_pastepile_key",storage:"local",suffix:"none",sensitivity:"secret",note:'Optional Pastepile API key plus its revocation secret. Free and account-less; it tags created pastes so they are listable under scope=mine ("My pastes"). Unscoped: it authorises this browser to talk to a pastebin, not one persona \u2014 which feeds a persona subscribes to stays per account. Retention-governed like the other pasted tokens.'},{base:"mockingbird_cors_proxy_key",storage:"local",suffix:"none",sensitivity:"secret",note:"CORS proxy API key, plus the header name a custom proxy wants it in. Billable on a paid plan, so it is retention-governed like the other pasted tokens. Unscoped: the subscription belongs to the human, not to one persona. Split out of mockingbird_cors_proxy so the proxy choice itself stays exportable."},{base:"mockingbird_shortener_keys",storage:"local",suffix:"none",sensitivity:"secret",note:"API keys for the link shorteners (Dub, Short.io, T.LY), one per service, each with its own retention stamp. A key here can create, re-point and delete links on a domain the user publishes under, so it is treated exactly like the other pasted tokens. Unscoped: the subscription belongs to the human, not to one persona. Split out of mockingbird_shortener so the service choice stays exportable."},{base:"mastodon_mock_sessions",storage:"local",suffix:"none",sensitivity:"private",note:"Which accounts on which instances. Identity, not credentials \u2014 the tokens live in mastodon_mock_session_tokens."},{base:"mastodon_mock_server",storage:"local",suffix:"none",sensitivity:"private",note:"Home instance. Names where the user is; a niche instance can be identifying on its own."},{base:"mockingbird_bsky_profile",storage:"local",suffix:"account",sensitivity:"private",note:"Linked Bluesky handle, DID, display name, avatar, resolved PDS."},{base:"mockingbird_github_user",storage:"local",suffix:"account",sensitivity:"private",note:"Linked GitHub login and profile."},{base:"mockingbird_anonymous_account",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"The browser-local Anonymous profile."},{base:"mockingbird_anonymous_follows",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Who the Anonymous account follows."},{base:"mockingbird_anonymous_bookmarks",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"What the Anonymous account saved."},{base:"mockingbird_anonymous_lists",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Anonymous account lists and their members."},{base:"mockingbird_anonymous_tags",storage:"local",suffix:"none",sensitivity:"private",group:"anonymous",note:"Followed hashtags. The canonical example of privacy-sensitive-but-not-secret: a health or identity tag published in a gist is a disclosure."},{base:"mockingbird_rss_feeds",storage:"local",suffix:"account",sensitivity:"private",note:"Subscribed feed URLs \u2014 what the user reads. Also near-secret: private feed URLs (Feedbin, Miniflux, Google Alerts) routinely embed an API key in the URL itself. Each feed also carries its opt-in flag for the CORS proxy."},{base:"mockingbird_cors_proxy",storage:"local",suffix:"none",sensitivity:"private",note:"Which CORS proxy is selected, and a self-hosted proxy's URL template. Not secret \u2014 the key half lives in mockingbird_cors_proxy_key \u2014 but a custom template names a host the user runs."},{base:"mockingbird_shortener",storage:"local",suffix:"none",sensitivity:"private",note:"Which link shortener is active, and the short domain configured for each. Not secret \u2014 the keys live in mockingbird_shortener_keys \u2014 but a branded domain names the user, which is rather the point of one."},{base:"mockingbird_shortener_proxy_consent",storage:"local",suffix:"none",sensitivity:"private",note:"Which (shortener, CORS proxy) pairings the user agreed to send an API key through, and when. Holds no credential itself, but it records a security decision: exporting it and re-importing elsewhere would carry consent the person never gave in that browser."},{base:"mockingbird_paste_feeds",storage:"local",suffix:"account",sensitivity:"private",note:"Subscribed paste feeds \u2014 what the user reads, and whether each goes through the CORS proxy. Scoped per account: following a feed as one persona says nothing about what the others want in their timeline. An unscoped list from before that change is adopted by the first account to read it."},{base:"mockingbird_saved_searches",storage:"local",suffix:"account",sensitivity:"private",note:"Saved search terms. Reveals interests as directly as a tag subscription does."},{base:"mockingbird_local_moderation",storage:"local",suffix:"none",sensitivity:"private",note:"Muted words, accounts and domains. Often discloses more than a follow list."},{base:"mockingbird_muted_posts",storage:"local",suffix:"none",sensitivity:"private",note:"Individually hidden posts."},{base:"mockingbird_eliza_following",storage:"local",suffix:"account",sensitivity:"private",note:"Whether the local Eliza account is followed."},{base:"mockingbird_rail_profile",storage:"local",suffix:"account",sensitivity:"private",note:"Which profile cards are pinned to the rail \u2014 named accounts."},{base:"mockingbird_chat_read",storage:"local",suffix:"none",sensitivity:"private",note:"Per-conversation read markers; the conversation ids identify correspondents."},{base:"mockingbird_dismissed_announcements",storage:"local",suffix:"none",sensitivity:"private",note:"Dismissed announcement ids \u2014 server-specific, so it points at the instance."},{base:"mockingbird_house_ad_clicks",storage:"local",suffix:"none",sensitivity:"private",note:"How many times each right-rail house ad was clicked, and when. Local only \u2014 never sent anywhere."},{base:"mockingbird_route_log",storage:"local",suffix:"none",sensitivity:"private",note:"Per-route visit counts and time spent, for the Observability page. Paths are sanitized (no ids or queries). Local only \u2014 never sent anywhere."},{base:"mockingbird_drafts",storage:"local",suffix:"none",sensitivity:"content",note:"Unpublished post drafts."},{base:"mockingbird_compose_autosave",storage:"local",suffix:"none",sensitivity:"content",note:"In-progress composer text."},{base:"mockingbird_pastes",storage:"local",suffix:"none",sensitivity:"content",note:"Paste history including bodies. Edit codes are NOT here \u2014 see mockingbird_paste_edit_keys."},{base:"mockingbird_short_links",storage:"local",suffix:"none",sensitivity:"content",note:"Short links this browser created: destination, short URL and the provider id needed to edit or delete them. Content rather than private because the destinations are things the user chose to publish. Link passwords are deliberately never stored here."},{base:"mockingbird_eliza_dm",storage:"local",suffix:"account",sensitivity:"content",note:"Local DM threads."},{base:"mockingbird_local_posts",storage:"local",suffix:"account",sensitivity:"content",note:"Locally-composed posts."},{base:"mockingbird_eliza_notifications",storage:"local",suffix:"account",sensitivity:"content",note:"Locally-generated notifications."},{base:"mockingbird_client_prefs",storage:"local",suffix:"none",sensitivity:"setting",note:"Theme, accent, reader typography, composer behaviour. The bulk of a shareable setup."},{base:"mockingbird_house_ads",storage:"local",suffix:"none",sensitivity:"setting",note:"Whether right-rail house ads show at all, and which ones are switched off individually. Unscoped: an opinion about an ad belongs to the person, not to one persona."},{base:"mockingbird_default_visibility",storage:"local",suffix:"account",sensitivity:"setting",note:"Default post visibility."},{base:"mockingbird_hidden_providers",storage:"local",suffix:"account",sensitivity:"setting",note:"Which providers are hidden from the merged timeline."},{base:"mockingbird_just_my_server",storage:"local",suffix:"account",sensitivity:"setting",note:"Whether Home uses the generated same-server friends list."},{base:"mockingbird_feature_flags",storage:"local",suffix:"none",sensitivity:"setting",note:"Opt-in feature toggles."},{base:"mockingbird_credential_lifetime",storage:"local",suffix:"account",sensitivity:"setting",note:"Connector credential retention policy (30d / 90d / never)."},{base:"mockingbird_anonymous_preferences",storage:"local",suffix:"none",sensitivity:"setting",group:"anonymous",note:"Preferences for the Anonymous account."},{base:"mockingbird_search_server_v1",storage:"local",suffix:"none",sensitivity:"setting",note:"Optional separate search instance. Names a host, but choosing one is a config tip worth sharing."},{base:"mockingbird_translation_preference",storage:"local",suffix:"none",sensitivity:"setting",note:"Which translator the \u{1F310} button uses: your server, AI via OpenRouter, or ask each time. Absent means the default (your server)."},{base:"mockingbird_client_lists",storage:"local",suffix:"account",sensitivity:"setting",note:"Browser-local lists of accounts, stored as handles. Works signed out, and unlike server lists does not require following anyone. Treated as cache: a version bump discards it."},{base:"mockingbird_tag_bundles",storage:"local",suffix:"account",sensitivity:"setting",note:"Named bundles of hashtags read as one feed, capped at 10 tags each. Works signed out. Treated as cache: a version bump discards it."},{base:"mockingbird_translation_usage",storage:"local",suffix:"none",sensitivity:"setting",note:"Daily translation counts and limits, held separately for the Mastodon endpoint and OpenRouter. Counts only \u2014 never what was translated."},{base:"mockingbird_search_server_rejects_v1",storage:"local",suffix:"none",sensitivity:"setting",note:"Servers already checked and rejected as search servers, so a hunt does not re-probe the same duds. Clearable from Settings \u2192 Server."},{base:"mockingbird_follow_nudge_dismissed",storage:"local",suffix:"none",sensitivity:"setting",note:"Whether the follow nudge was dismissed."},{base:"mastodon_mock_account_mode",storage:"local",suffix:"none",sensitivity:"setting",note:"Whether the last session was a Mastodon account or Anonymous."},{base:"mastodon_mock_server_index",storage:"local",suffix:"none",sensitivity:"cache",note:"Curated joinmastodon instance index."},{base:"mockingbird_server_about_v1",storage:"local",suffix:"none",sensitivity:"cache",note:"Cached instance /about payloads."},{base:"mockingbird_cors_proxy_usage",storage:"local",suffix:"none",sensitivity:"cache",note:"Counts of proxied requests and failures, for the Observability page. Diagnostics, not settings \u2014 resetting them loses nothing. Deliberately counters only: no URLs, so it never records which feeds were read."},{base:"mockingbird_search_server_about_v1",storage:"local",suffix:"none",sensitivity:"cache",note:"Cached search-instance /about payloads."},{base:"mockingbird_instance_status_pages",storage:"local",suffix:"none",sensitivity:"cache",note:"Discovered instance status pages."},{base:"mockingbird_api_metrics:",storage:"local",suffix:"instance",sensitivity:"cache",note:"Local API timing metrics and grouped client-error counts, one entry per instance. The trailing colon is part of the base \u2014 keys are `\u2026metrics:<host>`."},{base:"mockingbird_api_metrics",storage:"local",suffix:"none",sensitivity:"cache",note:"Superseded unscoped metrics blob, replaced by the per-instance keys above. Only ever deleted now; classified so lingering data is still recognised."},{base:"mockingbird_anonymous_home_feed",storage:"local",suffix:"none",sensitivity:"cache",group:"anonymous",note:"Cached Anonymous home timeline. Derived from private follow data."},{base:"mockingbird_anonymous_feed_corpus",storage:"local",suffix:"none",sensitivity:"cache",group:"anonymous",note:"Cached posts backing the Anonymous feed. Derived from private follow data."},{base:"mockingbird_raindrop_credentials",storage:"local",suffix:"account",sensitivity:"secret",note:"Legacy key from the superseded Raindrop OAuth flow. Only ever deleted now, never written; listed so it is classified if it lingers."},{base:"mastodon_mock_oauth_app",storage:"session",suffix:"none",sensitivity:"secret",note:"In-flight Mastodon OAuth attempt: client secret, PKCE verifier and state."},{base:"mockingbird_openrouter_key",storage:"local",suffix:"none",sensitivity:"secret",note:"OpenRouter API key from the PKCE flow. Can spend the user\u2019s OpenRouter credits. Shared by every account in this browser."},{base:"mockingbird_openrouter_model",storage:"local",suffix:"none",sensitivity:"setting",note:"Chosen OpenRouter model id for the prompt helpers."},{base:"mockingbird_openrouter_prompts",storage:"local",suffix:"none",sensitivity:"setting",note:"User-edited prompt templates for the search and tag helpers. Only present for templates edited away from the shipped default."},{base:"mockingbird_config_sync",storage:"local",suffix:"none",sensitivity:"private",note:"Remote configuration URL, check cadence, last verified hash, and check timestamp. Operational sync state is never included in a portable config."},{base:"mockingbird_openrouter_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight OpenRouter authorization."},{base:"mockingbird_openrouter_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight OpenRouter authorization."},{base:"mockingbird_dropbox_token",storage:"session",suffix:"none",sensitivity:"secret",note:"Short-lived Dropbox online access token."},{base:"mockingbird_dropbox_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight Dropbox authorization."},{base:"mockingbird_dropbox_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight Dropbox authorization."},{base:"mockingbird_blogger_token",storage:"session",suffix:"account",sensitivity:"secret",note:"Short-lived Google access token."},{base:"mockingbird_blogger_blog",storage:"local",suffix:"account",sensitivity:"private",note:"Chosen Blogger blog (id, name, address) and the profile-feed opt-in."},{base:"mockingbird_blogger_client_id",storage:"local",suffix:"none",sensitivity:"setting",note:"The user's own Google OAuth client id, overriding the build's."},{base:"mockingbird_blogger_pkce_verifier",storage:"session",suffix:"none",sensitivity:"secret",note:"PKCE verifier for the in-flight Blogger authorization."},{base:"mockingbird_blogger_oauth_state",storage:"session",suffix:"none",sensitivity:"secret",note:"Anti-CSRF state for the in-flight Blogger authorization."},{base:"mockingbird.update-recovery",storage:"session",suffix:"none",sensitivity:"cache",note:"Reload-attempt bookkeeping for post-deployment chunk recovery."}];function i(t,e){switch(t.suffix){case"none":return e===t.base;case"account":return e===t.base||e.startsWith(`${t.base}_`);case"instance":return e.startsWith(t.base)}}function n(t){let e=null;for(let s of o)i(s,t)&&(e===null||s.base.length>e.base.length)&&(e=s);return e}export{o as a,i as b,n as c};
